//! Generated byte pipes only: poisoning is not shutdown or physical-close proof.
use std::future::Future;
use std::io;
use std::pin::{pin, Pin};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};

use velmora::nntp::{NntpClient, NntpConfig};
use velmora::transport::{BufferedTransport, Transport, MAX_ARTICLE_BYTES};

#[derive(Default, Clone, PartialEq, Eq, Debug)]
struct Trace {
    reads: usize,
    writes: Vec<u8>,
    shutdowns: usize,
    drops: usize,
}

struct Script {
    input: Vec<u8>,
    stall_write: bool,
    cleanup: u8,
    trace: Arc<Mutex<Trace>>,
}

impl Drop for Script {
    fn drop(&mut self) {
        self.trace.lock().unwrap().drops += 1;
    }
}

impl Transport for Script {
    async fn read(&mut self, out: &mut [u8]) -> io::Result<usize> {
        self.trace.lock().unwrap().reads += 1;
        if self.input.is_empty() {
            std::future::pending::<()>().await;
        }
        let n = out.len().min(self.input.len());
        out[..n].copy_from_slice(&self.input[..n]);
        self.input.drain(..n);
        Ok(n)
    }

    async fn write_all(&mut self, bytes: &[u8]) -> io::Result<()> {
        self.trace.lock().unwrap().writes.extend_from_slice(bytes);
        if self.stall_write {
            std::future::pending::<()>().await;
        }
        Ok(())
    }

    async fn shutdown(&mut self) -> io::Result<()> {
        self.trace.lock().unwrap().shutdowns += 1;
        match self.cleanup {
            0 => Ok(()),
            1 => Err(io::ErrorKind::ConnectionReset.into()),
            _ => std::future::pending().await,
        }
    }
}

fn script(input: &[u8], stall_write: bool, cleanup: u8) -> (Script, Arc<Mutex<Trace>>) {
    let trace = Arc::new(Mutex::new(Trace::default()));
    (
        Script {
            input: input.to_vec(),
            stall_write,
            cleanup,
            trace: trace.clone(),
        },
        trace,
    )
}

fn poll_once<F: Future>(f: Pin<&mut F>) -> Poll<F::Output> {
    f.poll(&mut Context::from_waker(Waker::noop()))
}

async fn exchange(t: &mut BufferedTransport<Script>, operation: u8) -> io::Result<()> {
    match operation {
        0 => t.read_line().await.map(|_| ()),
        1 => t.write_line(b"STAT <generated@test>").await,
        _ => t.write_dot_block(b"generated\r\n").await,
    }
}

#[tokio::test]
async fn dropping_polled_exchanges_poisons_without_more_io() {
    for operation in 0..3 {
        let (inner, trace) = script(b"", true, 0);
        let mut t = BufferedTransport::new(inner);
        {
            let mut future = pin!(exchange(&mut t, operation));
            assert!(poll_once(future.as_mut()).is_pending());
        }
        let before = trace.lock().unwrap().clone();
        for next in 0..3 {
            assert_eq!(
                exchange(&mut t, next).await.unwrap_err().kind(),
                io::ErrorKind::BrokenPipe
            );
        }
        let mut out = b"prefix".to_vec();
        assert_eq!(
            t.read_dot_block(&mut out).await.unwrap_err().kind(),
            io::ErrorKind::BrokenPipe
        );
        assert_eq!(out, b"prefix");
        assert_eq!(*trace.lock().unwrap(), before);
        assert_eq!(before.shutdowns, 0);
        assert_eq!(before.drops, 0);
    }
}

#[tokio::test]
async fn unpolled_and_completed_exchanges_preserve_reuse() {
    for operation in 0..3 {
        let (inner, trace) = script(b"200 generated\r\n", false, 0);
        let mut t = BufferedTransport::new(inner);
        drop(exchange(&mut t, operation));
        assert_eq!(*trace.lock().unwrap(), Trace::default());
        exchange(&mut t, operation).await.unwrap();
        t.write_line(b"NOOP").await.unwrap();
        assert_eq!(trace.lock().unwrap().shutdowns, 0);
    }
}

#[tokio::test]
async fn caller_owned_cleanup_poisons_before_success_failure_or_pending() {
    for cleanup in 0..3 {
        let (inner, trace) = script(b"200 ready\r\n200 reader\r\n", false, cleanup);
        let mut client = NntpClient::connect(inner, &NntpConfig::default())
            .await
            .unwrap();
        {
            let mut future = pin!(client.shutdown_unusable());
            match (cleanup, poll_once(future.as_mut())) {
                (0, Poll::Ready(Ok(()))) | (2, Poll::Pending) => {}
                (1, Poll::Ready(Err(e))) => assert_eq!(e.kind(), io::ErrorKind::ConnectionReset),
                _ => panic!("unexpected cleanup result"),
            }
        }
        let before = trace.lock().unwrap().clone();
        assert_eq!(before.shutdowns, 1);
        assert_eq!(before.drops, 0, "cleanup still borrows a live transport");
        assert!(client.stat("generated@test").await.is_err());
        assert_eq!(*trace.lock().unwrap(), before);
        drop(client);
        let after = trace.lock().unwrap().clone();
        assert_eq!(after.drops, 1);
        assert_eq!(after.writes, b"MODE READER\r\n");
        // Drop and shutdown counters record attempts, never external close confirmation.
    }
}

#[tokio::test]
async fn abandoned_client_commands_never_reuse_the_stream_or_send_quit() {
    for operation in 0..4 {
        let reply: &[u8] = match operation {
            1 => b"340 send article\r\n",
            2 => b"222 1 <generated@test>\r\n",
            _ => b"",
        };
        let mut input = b"200 ready\r\n200 reader\r\n".to_vec();
        input.extend_from_slice(reply);
        let (inner, trace) = script(&input, false, 0);
        let mut client = NntpClient::connect(inner, &NntpConfig::default())
            .await
            .unwrap();
        let mut out = b"prefix".to_vec();
        {
            let mut future = pin!(async {
                match operation {
                    0 | 1 => client
                        .post_article("generated@test", b"body\r\n")
                        .await
                        .map(|_| ()),
                    2 => client.body_to("generated@test", &mut out).await,
                    _ => client.stat("generated@test").await.map(|_| ()),
                }
            });
            assert!(poll_once(future.as_mut()).is_pending());
        }
        let before = trace.lock().unwrap().clone();
        assert!(client.stat("generated@test").await.is_err());
        assert_eq!(*trace.lock().unwrap(), before);
        assert_eq!(out, b"prefix");
        client.quit().await;
        let after = trace.lock().unwrap();
        assert_eq!(after.writes, before.writes);
        assert_eq!(after.shutdowns, 1);
    }
}

#[tokio::test]
async fn effective_article_cap_reports_configured_clamped_bound() {
    let (inner, _) = script(b"", false, 0);
    let t = BufferedTransport::with_article_limit(inner, usize::MAX);
    assert_eq!(t.max_article_bytes(), MAX_ARTICLE_BYTES);
    let (inner, _) = script(b"200 ready\r\n200 reader\r\n", false, 0);
    let config = NntpConfig {
        max_article_bytes: 512,
        ..NntpConfig::default()
    };
    let client = NntpClient::connect(inner, &config).await.unwrap();
    assert_eq!(client.max_article_bytes(), 512);
}
